import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.PU0FRLnN.js";import"./chunks/assets.BHTds6ax.js";var i=JSON.parse(`{"title":"Schema & Stability","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema.md","filePath":"reference/schema.md"}`),a={name:`reference/schema.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="schema-stability" tabindex="-1">Schema &amp; Stability <a class="header-anchor" href="#schema-stability" aria-label="Permalink to “Schema &amp; Stability”">​</a></h1><p>This page documents the machine-readable contract for the <strong>JSON</strong> and <strong>Graphify</strong> formats. If you&#39;re building tooling on top of GraphScribe (or feeding exports to an AI agent), this is what you need to know. If you just want to read exports, you can skip this page.</p><h2 id="version-stamps" tabindex="-1">Version stamps <a class="header-anchor" href="#version-stamps" aria-label="Permalink to “Version stamps”">​</a></h2><p>Every JSON and Graphify document carries identity fields at its root:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th><th>Where</th><th>Meaning</th></tr></thead><tbody><tr><td><code>generator</code></td><td><code>&quot;GraphScribe&quot;</code></td><td>JSON + Graphify</td><td>Producer name</td></tr><tr><td><code>generatorVersion</code></td><td><code>&quot;1.0.0&quot;</code></td><td>JSON + Graphify</td><td>Plugin version (kept in sync with <code>VersionName</code> in <code>GraphScribe.uplugin</code>)</td></tr><tr><td><code>schemaVersion</code></td><td><code>1</code></td><td>JSON root</td><td>Shape of the <code>EmitJson</code> IR (variables/nodes/edges/diagnostics/…)</td></tr><tr><td><code>schemaVersion</code></td><td><code>1</code></td><td>Graphify root</td><td>Shape of <code>EmitGraphify</code> + merge linkage</td></tr><tr><td><code>dumpMode</code></td><td><code>full</code> / <code>modifiedOnly</code> / <code>blueprintOnly</code></td><td>JSON + Graphify root</td><td>Optional property dump mode used for this document (<a href="/GraphScribe-Docs/guide/settings.html">settings</a>)</td></tr></tbody></table><p><code>dumpMode</code> is stamped on per-asset documents only. The merged <code>ProjectLinkage.graphify.json</code> carries <code>schemaVersion</code> / <code>generator</code> / <code>generatorVersion</code> but no <code>dumpMode</code> (a merge can combine per-asset files produced under different modes).</p><p>Markdown and Mermaid are <strong>not</strong> versioned, they are human-readable views with no machine contract. Treat their exact wording as unstable across releases.</p><p><img src="/GraphScribe-Docs/img/json-output-file.png" alt="The version stamps at the root of a JSON export" width="615" height="433"></p><h2 id="json-document-shape" tabindex="-1">JSON document shape <a class="header-anchor" href="#json-document-shape" aria-label="Permalink to “JSON document shape”">​</a></h2><p>Root fields of an <code>EmitJson</code> document (see <a href="/GraphScribe-Docs/guide/json-output.html">JSON Output</a> for examples):</p><p><code>title</code>, <code>blueprint</code>, <code>assetPath</code>, <code>parentClass</code>, <code>isWidgetBlueprint</code>, <code>isDataAsset</code>, <code>variables[]</code>, <code>widgetTree[]</code>, <code>animations[]</code>, <code>classRefs[]</code>, <code>nodes[]</code> (each with <code>pins[]</code>), <code>edges[]</code>, <code>diagnostics[]</code>.</p><h2 id="graphify-document-shape" tabindex="-1">Graphify document shape <a class="header-anchor" href="#graphify-document-shape" aria-label="Permalink to “Graphify document shape”">​</a></h2><p><strong>Nodes</strong> (<code>nodes[]</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td>Stable id to <code>bp:</code> / <code>fn:</code> / <code>cls:</code> for linkage, <code>var_...</code> for variable rows, <code>widget_N</code> for widget-tree rows</td></tr><tr><td><code>label</code></td><td>Display label (truncated for long variable values)</td></tr><tr><td><code>file_type</code></td><td>Always <code>&quot;code&quot;</code></td></tr><tr><td><code>source_file</code></td><td>Asset path the node came from</td></tr><tr><td><code>source_location</code></td><td>Optional e.g. <code>&quot;Variables&quot;</code>, <code>&quot;ClassRefHard&quot;</code>, <code>&quot;Linkage&quot;</code></td></tr><tr><td><code>origin</code> / <code>hasChildren</code> / <code>category</code> / <code>declaringClass</code></td><td>Optional variable-row metadata</td></tr></tbody></table><p><strong>Edges</strong> (<code>edges[]</code>): <code>source</code>, <code>target</code>, <code>relation</code>, <code>confidence</code> (always <code>&quot;EXTRACTED&quot;</code>), <code>source_file</code>.</p><h2 id="the-graphify-stability-contract" tabindex="-1">The Graphify stability contract <a class="header-anchor" href="#the-graphify-stability-contract" aria-label="Permalink to “The Graphify stability contract”">​</a></h2><p>The most important guarantees for tooling:</p><h3 id="_1-ids-are-stable-across-exports" tabindex="-1">1. IDs are stable across exports <a class="header-anchor" href="#_1-ids-are-stable-across-exports" aria-label="Permalink to “1. IDs are stable across exports”">​</a></h3><ul><li><code>bp:&lt;AssetPath&gt;</code> a Blueprint or DataAsset</li><li><code>fn:&lt;AssetPath&gt;::&lt;FunctionName&gt;</code> a function inside an asset</li><li><code>cls:&lt;ClassPath&gt;</code> a class reference</li></ul><p>These are derived from asset/class <strong>identity</strong>, not from node GUIDs or graph layout. A consumer can persist an ID and re-resolve it after a re-export.</p><h3 id="_2-relations-are-a-closed-set" tabindex="-1">2. Relations are a closed set <a class="header-anchor" href="#_2-relations-are-a-closed-set" aria-label="Permalink to “2. Relations are a closed set”">​</a></h3><p>The merge step only understands these relations: <strong><code>calls</code></strong>, <strong><code>defines</code></strong>, <strong><code>uses</code></strong>. Per-asset Graphify may also emit <code>contains</code> for local structure (widget tree / variable nesting), the merge drops it. If a new relation is ever added to the merge, that&#39;s a schema bump.</p><h3 id="_3-merge-is-forward-compatible" tabindex="-1">3. Merge is forward-compatible <a class="header-anchor" href="#_3-merge-is-forward-compatible" aria-label="Permalink to “3. Merge is forward-compatible”">​</a></h3><p><code>MergeGraphifyLinkage</code> / <code>MergeGraphifyLinkageFromDirectory</code>:</p><ul><li>skip malformed or empty inputs,</li><li>deduplicate stable nodes (first one wins),</li><li>deduplicate identical <code>source|relation|target</code> edges,</li><li>drop edges whose endpoints aren&#39;t stable IDs,</li><li>pass through unknown object fields.</li></ul><p>So adding optional fields does <strong>not</strong> break older consumers. The batch merge re-reads every <code>*.graphify.json</code> under the output directory (skipping <code>ProjectLinkage.graphify.json</code> itself), so folder-by-folder exports accumulate.</p><h3 id="_4-diagnostics-use-one-shape" tabindex="-1">4. Diagnostics use one shape <a class="header-anchor" href="#_4-diagnostics-use-one-shape" aria-label="Permalink to “4. Diagnostics use one shape”">​</a></h3><p>Documents carry a <code>&quot;diagnostics&quot;</code> array only. There is no legacy <code>&quot;warnings&quot;</code> string array. See <a href="/GraphScribe-Docs/reference/diagnostics.html">Diagnostics Codes</a>.</p><h2 id="when-to-bump-schemaversion" tabindex="-1">When to bump <code>schemaVersion</code> <a class="header-anchor" href="#when-to-bump-schemaversion" aria-label="Permalink to “When to bump schemaVersion”">​</a></h2><p>Bump the relevant <code>schemaVersion</code> (and document it in the changelog) when a change is <strong>not backward-compatible</strong> for a consumer that already parses the current shape:</p><ul><li>Renaming or removing a required field from <code>nodes</code> / <code>edges</code> / variables.</li><li>Changing the meaning of an existing field (e.g. what <code>id</code> points at).</li><li>Adding a new <code>relation</code> to the Graphify merge closed set.</li><li>Changing the Graphify ID grammar (<code>bp:</code> / <code>fn:</code> / <code>cls:</code> prefixes or the <code>::</code> separator).</li></ul><p>Do <strong>not</strong> bump for:</p><ul><li>Adding an <strong>optional</strong> field consumers can ignore (forward-compatible).</li><li>Markdown/Mermaid wording changes.</li><li>Bug fixes that make output match the documented shape.</li><li>Adding a new diagnostic <code>code</code> (consumers must ignore unknown codes).</li></ul><p><code>generatorVersion</code> follows the plugin&#39;s semver and may move independently of <code>schemaVersion</code>. A schema bump should also be called out in the changelog under the release that introduced it.</p>`,34)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};